-- Nintendo Switch 2, as a console of its own.
--
-- IGDB has listed Switch 2 (its platform 508) since launch, but the importer
-- folded it into Switch, so a Switch 2 game read as a Switch game and nobody
-- could log the one they played. This adds the console beside Switch, in the
-- same family, and puts the catalogue right from IGDB's own lists as of
-- 2026-10-07: every game IGDB has on Switch 2 gains it, and the ones that are
-- on Switch 2 alone lose the Switch they never had. Logs are left as they are.
--
-- Also: "PC Game Pass" becomes "Game Pass". It is offered on any PC or Xbox
-- game (see shared/src/schemas/game.ts), so the PC in its name was wrong.

set search_path = pg_catalog, public;

values ('nintendo-switch-2', 'Nintendo Switch 2', 'nintendo-switch', 5)
on conflict (slug) do nothing;

update public.platform_systems set display_name = 'Game Pass' where slug = 'pc-game-pass';
update public.platforms set display_name = 'Game Pass' where slug = 'pc-game-pass';

-- On Switch and Switch 2.
create temporary table switch2_both (igdb_id bigint);

-- On Switch 2 alone.
create temporary table switch2_only (igdb_id bigint);

select g.id, 'nintendo-switch-2'
from public.games g
where g.igdb_id in (select igdb_id from switch2_both union select igdb_id from switch2_only)
on conflict do nothing;

delete from public.game_systems gs
using public.games g
where gs.game_id = g.id
  and gs.system_slug = 'nintendo-switch'
  and g.igdb_id in (select igdb_id from switch2_only);

-- The family stays: Switch 2 is in the Switch family, so game_platforms
-- already says nintendo-switch for every one of these games.

drop table switch2_both;
drop table switch2_only;
